export function getChapter3And4TopicQuestions(topicCode: string): SeedQuestionItem[] {
  const list = CH3_CH4_TOPICS[topicCode] || CH3_CH4_TOPICS['C3-B1'];
  return list.map((q, idx) => ({
    ...q,
    order_index: idx + 1,
  }));
}

/**
 * Generates 25 comprehensive synthesis exam questions for each Chapter (CH1, CH2, CH3, CH4)
 * by selecting a balanced matrix across all topics in that chapter + cross-topic synthesis problems!
 */
export function buildChapter25ExamQuestions(chapterCode: string): SeedQuestionItem[] {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { buildTopic25Questions } = require('./grade6-questions');

  const chapterTopicMap: Record<string, string[]> = {
    CH1: ['C1-B1', 'C1-B2', 'C1-B3'],
    CH2: ['C2-B1', 'C2-B2', 'C2-B3', 'C2-B4', 'C2-B5', 'C2-B6'],
    CH3: ['C3-B1', 'C3-B2', 'C3-B3'],
    CH4: ['C4-B1', 'C4-B2', 'C4-B3'],
  };

  const topicCodes = chapterTopicMap[chapterCode] || ['C1-B1', 'C1-B2', 'C1-B3'];
  const allTopicPools: SeedQuestionItem[][] = topicCodes.map((code) => buildTopic25Questions(code));

  const selected: Omit<SeedQuestionItem, 'order_index'>[] = [];

  // Interleave questions across topics and across difficulties (10 nhan_biet, 7 thong_hieu, 5 van_dung, 3 van_dung_cao = 25)
  const targetCounts: { diff: SeedQuestionItem['difficulty']; count: number }[] = [
    { diff: 'nhan_biet', count: 10 },
    { diff: 'thong_hieu', count: 7 },
    { diff: 'van_dung', count: 5 },
    { diff: 'van_dung_cao', count: 3 },
  ];

  for (const { diff, count } of targetCounts) {
    const candidates: SeedQuestionItem[] = [];
    const maxLen = 25;
    for (let i = 0; i < maxLen; i++) {
      for (let t = 0; t < allTopicPools.length; t++) {
        const q = allTopicPools[t][i];
        if (q && q.difficulty === diff) {
          candidates.push(q);
        }
      }
    }
    for (let k = 0; k < Math.min(count, candidates.length); k++) {
      selected.push({
        difficulty: candidates[k].difficulty,
        question_text: `[Tổng hợp ${chapterCode}] ${candidates[k].question_text}`,
        options: candidates[k].options,
        correct_index: candidates[k].correct_index,
        explanation: candidates[k].explanation,
      });
    }
  }

  return selected.slice(0, 25).map((q, idx) => ({
    ...q,
    order_index: idx + 1,
  }));
}
